// === Tab: mySketch ===
let campfireSketch = (p) => {
  // --- Config ---
  const MAX_DPR = 1.6; // cap for performance across devices
  const TARGET_FPS = 60;
  const LOW_FPS = 36; // drop quality if below

  let DPR = 1;
  let qualityScale = 1;

  // Scene state
  let t = 0;                 // global time
  let wind = 0;              // -1..1
  let heat = 1;              // base flame energy
  let phoenixMode = 0;       // 0..1 tween
  let phoenixTimer = 0;      // counts down when active
  let typed = "";            // for secret codes

  // Entities
  let embers = [];
  let words = [];
  let flies = [];

  // Misc
  let runePhase = 0;
  let fontStack = 'system-ui, -apple-system, Segoe UI, Roboto, Ubuntu, Cantarell, Noto Sans, Helvetica Neue, Arial';

  // Story words (iconic campfire themes)
  const STORY = [
    'legend', 'embers', 'wander', 'echo', 'myth', 'spark', 'constellations', 'home', 'tales', 'ghost',
    'belonging', 'wild', 'north', 'river', 'silence', 'memory', 'kin', 'moonlight', 'roots', 'future',
    'courage', 'rift', 'promise', 'secret', 'song', 'campfire'
  ];

  p.setup = () => {
    DPR = p.min(MAX_DPR, p.pixelDensity());
    p.pixelDensity(DPR);
    p.createCanvas(p.windowWidth, p.windowHeight, p.P2D);
    p.frameRate(60);
    initScene();
  };

  function initScene() {
    // seed
    p.randomSeed(20251020);
    p.noiseSeed(20251020);

    // initialize fireflies
    const flyCount = p.floor(30 * baseScale());
    flies = [];
    for (let i = 0; i < flyCount; i++) flies.push(new Firefly());

    embers = [];
    words = [];
    for (let i = 0; i < 60 * baseScale(); i++) embers.push(new Ember(true));
  }

  function baseScale() {
    // scales with screen area (normalized to 1440x900 ≈ 1.3e6 px)
    const area = p.width * p.height;
    return p.constrain(p.sqrt(area / 1300000), 0.6, 1.6) * qualityScale;
  }

  p.windowResized = () => {
    DPR = p.min(MAX_DPR, p.pixelDensity());
    p.pixelDensity(DPR);
    p.resizeCanvas(p.windowWidth, p.windowHeight);
  };

  p.draw = () => {
    // adaptive quality: if FPS drops, reduce qualityScale a touch
    const fps = p.frameRate();
    if (p.frameCount % 15 === 0) {
      if (fps < LOW_FPS) qualityScale = p.max(0.75, qualityScale * 0.98);
      else if (fps > TARGET_FPS - 3) qualityScale = p.min(1.0, qualityScale * 1.01);
    }

    t += 0.016 * p.constrain(heat, 0.8, 2.0);
    wind = p.lerp(wind, p.movedX * 0.006, 0.05); // coax wind via horizontal drag

    drawSky();
    drawStars();
    drawHorizon();

    // camp ring & ground
    drawRing();

    // flames & embers
    drawFlames();
    updateAndDrawEmbers();

    // interactive words
    updateAndDrawWords();

    // fireflies
    updateAndDrawFlies();

    // UI overlays
    drawUI();

    // phoenix mode decay
    if (phoenixTimer > 0) {
      phoenixTimer -= p.deltaTime / 1000;
      phoenixMode = p.lerp(phoenixMode, 1, 0.05);
    } else {
      phoenixMode = p.lerp(phoenixMode, 0, 0.04);
    }
  };

  // --- Drawing helpers ---
  function drawSky() {
    // Vertical gradient night sky with subtle noise
    for (let y = 0; y < p.height; y += 2) {
      const k = y / p.height;
      const c = p.lerpColor(p.color(10, 12, 20), p.color(2, 4, 9), k);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }
  }

  function drawStars() {
    // Implicit parallax stars using noise — cheap but pretty
    p.push();
    p.noStroke();
    const n = 200 * baseScale();
    const mx = p.constrain(p.mouseX || p.width / 2, 0, p.width);
    const my = p.constrain(p.mouseY || p.height / 3, 0, p.height);
    for (let i = 0; i < n; i++) {
      const a = p.random(i + 1) * 9999;
      const x = p.noise(i * 0.173, 0.1) * p.width;
      const y = p.noise(i * 0.173, 0.9) * p.height * 0.6;
      const par = 0.004 + (i % 5) * 0.002;
      const px = x + (mx - p.width / 2) * par;
      const py = y + (my - p.height / 2) * par;
      p.fill(255, 255, 230, 120 + (i % 5) * 30);
      p.circle(px, py, p.random(0.5, 1.6));
    }
    p.pop();
  }

  function drawHorizon() {
    p.push();
    var y = p.height * 0.72;
    // distant treeline silhouette
    p.noStroke();
    for (let x = 0; x <= p.width; x += 12) {
      const h = 30 + 50 * p.noise(x * 0.01, 7.77);
      p.fill(8, 12, 10);
      p.rect(x, y - h, 12, h + 2000);
    }

    // foreground ground gradient
    for (let i = 0; i < 120; i++) {
      const yy = y + i;
      var c = p.lerpColor(p.color(12, 10, 8), p.color(4, 4, 5), i / 120);
      p.stroke(c);
      p.line(0, yy, p.width, yy);
    }
    p.pop();
  }

  function drawRing() {
    p.push();
    const cx = p.width * 0.5;
    const cy = p.height * 0.72;

    // stones
    p.noStroke();
    const R = 120 * baseScale();
    for (let i = 0; i < 12; i++) {
      var a = (i / 12) * p.TWO_PI + p.noise(i, t * 0.2) * 0.2;
      const rr = R + p.noise(i * 3.1, 9.9) * 18;
      var x = cx + p.cos(a) * rr;
      var y = cy + p.sin(a) * (rr * 0.45);
      p.fill(40, 40, 48);
      p.ellipse(x, y, 36, 22);
      p.fill(26, 26, 32);
      p.ellipse(x, y + 2, 36, 22);
    }

    // logs (simple triangles)
    p.push();
    p.translate(cx, cy + 8);
    p.rotate(0.08);
    drawLog(-26, 14, 1);
    drawLog(22, 18, -1);
    drawLog(-6, 8, 1);
    p.pop();

    // subtle glow
    const rad = 180 * baseScale();
    const grad = p.drawingContext.createRadialGradient(cx, cy, 1, cx, cy, rad);
    grad.addColorStop(0, 'rgba(255,160,60,0.22)');
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    p.drawingContext.fillStyle = grad;
    p.noStroke();
    p.ellipse(cx, cy, rad * 2.0, rad * 1.2);

    p.pop();
  }

  function drawLog(x, y, flip) {
    p.push();
    p.translate(x, y);
    p.scale(flip, 1);
    p.fill(70, 55, 35);
    p.quad(-60, 10, 60, -10, 58, 8, -58, 28);
    p.fill(96, 76, 45);
    p.quad(-60, 10, 60, -10, 64, -6, -64, 14);
    // rings on cut
    p.fill(120, 100, 70);
    p.ellipse(64, -8, 16, 12);
    p.pop();
  }

  function drawFlames() {
    p.push();
    var cx = p.width * 0.5;
    var cy = p.height * 0.72;
    const base = 90 * baseScale();
    var h = 240 * baseScale() * (0.8 + 0.5 * heat);

    p.blendMode(p.ADD);
    p.noStroke();

    // main noisy lobes
    for (let k = 0; k < 4; k++) {
      const alpha = 90 - k * 15;
      p.fill(255, 120 + k * 30, 30 + k * 15, alpha);
      p.beginShape();
      for (let a = -p.PI; a <= 0; a += p.PI / 30) {
        const nx = p.cos(a);
        const ny = -p.sin(a);
        const r = base * (0.8 + 0.2 * k) + 18 * p.noise(a * 1.7, t * 1.3 + k * 10);
        const fx = cx + nx * r + wind * 50 * (0.5 + k * 0.2);
        const fh = cy - ny * (h * (0.6 + 0.1 * k) + 90 * p.noise(a + t * 0.9, k + 7));
        p.vertex(fx, fh);
      }
      for (let a = 0; a <= p.PI; a += p.PI / 30) {
        var nx = p.cos(a);
        var ny = p.sin(a);
        var r = base * (0.9 - 0.15 * k) + 20 * p.noise(a * 1.9 + 99, t * 1.1 + k * 4);
        var fx = cx + nx * r + wind * 40 * (0.5 + k * 0.2);
        var fh = cy - ny * (40 + 12 * k);
        p.vertex(fx, fh);
      }
      p.endShape(p.CLOSE);
    }

    // core flare
    p.fill(255, 210, 120, 140);
    p.ellipse(cx + wind * 16, cy + 6, base * 0.9, base * 0.5);

    // phoenix silhouette overlay when active
    if (phoenixMode > 0.01) {
      drawPhoenix(cx, cy - h * 0.35, h * 0.9 * phoenixMode);
    }

    p.blendMode(p.BLEND);
    p.pop();
  }

  function drawPhoenix(x, y, s) {
    p.push();
    p.translate(x + wind * 30, y - 40 * p.sin(t * 2.2));
    p.scale(p.constrain(s / 240, 0.6, 1.4));
    p.noStroke();

    // glowing body
    p.fill(255, 170, 40, 120);
    p.ellipse(0, 0, 90, 60);

    // wings (oscillate)
    const fl = 120 + 30 * p.sin(t * 6.0);
    p.fill(255, 120, 30, 110);
    p.ellipse(-70, -10, fl, 40);
    p.ellipse(70, -10, fl, 40);

    // tail
    p.fill(255, 200, 80, 100);
    for (let i = 0; i < 6; i++) {
      p.ellipse(10 - i * 6, 28 + i * 10, 18, 40 + i * 18);
    }

    // head beak
    p.fill(255, 230, 150, 180);
    p.triangle(40, -8, 70, -4, 42, 6);

    // halo sparks
    p.fill(255, 230, 160, 90);
    for (let i = 0; i < 40; i++) {
      var a = (i / 40) * p.TWO_PI + t * 0.8;
      var r = 80 + 20 * p.noise(i * 1.3, t * 1.7);
      p.circle(p.cos(a) * r, p.sin(a) * r, 2 + (i % 3));
    }

    p.pop();
  }

  function updateAndDrawEmbers() {
    var cx = p.width * 0.5;
    var cy = p.height * 0.72;
    const count = 4 + p.floor(3 * baseScale() * heat);
    for (let i = 0; i < count; i++) embers.push(new Ember());

    p.blendMode(p.ADD);
    for (let i = embers.length - 1; i >= 0; i--) {
      const e = embers[i];
      e.step();
      e.draw();
      if (e.dead) embers.splice(i, 1);
    }
    p.blendMode(p.BLEND);
  }

  function updateAndDrawWords() {
    for (let i = words.length - 1; i >= 0; i--) {
      const w = words[i];
      w.step();
      w.draw();
      if (w.dead) words.splice(i, 1);
    }
  }

  function updateAndDrawFlies() {
    for (let i = 0; i < flies.length; i++) flies[i].step();
    for (let i = 0; i < flies.length; i++) flies[i].draw();
  }

  function drawUI() {
    // rune ring — reacts to input in a subtle, iconic way
    p.push();
    var cx = p.width * 0.5;
    var cy = p.height * 0.72;
    var R = 140 * baseScale();
    runePhase += 0.01 + 0.02 * (heat - 1);

    p.noFill();
    p.stroke(255, 140, 60, 40);
    p.strokeWeight(2);
    p.circle(cx, cy, R * 1.8);

    const runes = 'ᚠᚢᚦᚨᚱᚲᚷᚺᚾᛁᛃᛇᛈᛉᛊᛏᛒᛖᛗᛚᛝᛟ';
    p.textAlign(p.CENTER, p.CENTER);
    p.textSize(12 + 2 * baseScale());
    p.fill(255, 180, 120, 120);
    for (let i = 0; i < runes.length; i++) {
      var a = (i / runes.length) * p.TWO_PI + runePhase;
      var r = R * 0.9 + 4 * p.sin(t * 2 + i);
      var x = cx + p.cos(a) * r;
      var y = cy + p.sin(a) * (r * 0.55);
      p.push();
      p.translate(x, y);
      p.rotate(a + p.HALF_PI);
      p.text(runes[i], 0, 0);
      p.pop();
    }

    // hint (tiny, elegant)
    p.noStroke();
    p.fill(255, 230, 200, 90);
    p.textAlign(p.CENTER);
    p.textSize(12);
    p.textFont(fontStack);
    p.text('Drag wind · Tap to throw a word · Type PHOENIX · s = snapshot', p.width / 2, p.height - 20);
    p.pop();
  }

  // --- Entities ---
  class Ember {
    constructor(seedOnly=false) {
      var cx = p.width * 0.5;
      var cy = p.height * 0.72;
      this.x = cx + p.random(-20, 20);
      this.y = cy + p.random(-10, 4);
      this.vx = wind * p.random(10, 30) + p.random(-6, 6);
      this.vy = -p.random(60, 120) * (seedOnly ? p.random(0.2, 0.8) : 1);
      this.life = p.random(0.8, 1.6);
      this.age = 0;
      this.s = p.random(1, 2.8) * baseScale();
      this.dead = false;
    }
    step() {
      this.age += p.deltaTime / 1000;
      var a = -30 - 40 * heat + -10 * p.noise(this.x * 0.01, t);
      this.vx += 0.03 * wind + 0.02 * p.sin(t * 5 + this.age * 6);
      this.vy += a * 0.01;
      this.x += this.vx * 0.016;
      this.y += this.vy * 0.016;
      if (this.age > this.life) this.dead = true;
    }
    draw() {
      var k = 1 - p.constrain(this.age / this.life, 0, 1);
      p.fill(255, 180, 100, 120 * k);
      p.noStroke();
      p.circle(this.x, this.y, this.s * (1 + 1.5 * (1 - k)));
    }
  }

  class WordSpark {
    constructor(text, x, y) {
      this.text = text;
      this.x = x;
      this.y = y;
      this.vx = p.random(-20, 20) + wind * 40;
      this.vy = -p.random(60, 100) - 30 * heat;
      this.rot = p.random(-p.PI / 8, p.PI / 8);
      this.life = p.random(1.8, 3.2);
      this.age = 0;
      this.dead = false;
    }
    step() {
      this.age += p.deltaTime / 1000;
      this.vx += 0.05 * wind;
      this.vy += -18 * 0.02; // upward draft
      this.x += this.vx * 0.016;
      this.y += this.vy * 0.016;
      if (this.age > this.life) this.dead = true;
    }
    draw() {
      var k = 1 - p.constrain(this.age / this.life, 0, 1);
      p.push();
      p.translate(this.x, this.y);
      p.rotate(this.rot + 0.2 * p.sin(this.age * 6));
      p.textAlign(p.CENTER, p.CENTER);
      p.textFont(fontStack);
      p.textSize(18 + 6 * baseScale());
      p.fill(255, 210, 140, 200 * k);
      p.text(this.text, 0, 0);
      p.pop();
    }
  }

  class Firefly {
    constructor() {
      this.x = p.random(p.width);
      this.y = p.random(p.height * 0.6);
      this.vx = p.random(-20, 20);
      this.vy = p.random(-10, 10);
      this.targetX = this.x;
      this.targetY = this.y;
      this.phase = p.random(1000);
      this.size = p.random(1.5, 2.6) * baseScale();
    }
    step() {
      this.phase += 0.02;
      // gentle wander + avoid center heat column
      var cx = p.width * 0.5 + wind * 20;
      var cy = p.height * 0.62;
      const dx = this.x - cx;
      const dy = this.y - cy;
      const dist = p.sqrt(dx * dx + dy * dy);
      const repel = p.constrain(160 - dist, 0, 160) / 160;
      this.vx += (p.noise(this.phase, 0) - 0.5) * 0.8 + repel * (dx / (dist + 0.01)) * 0.6;
      this.vy += (p.noise(0, this.phase) - 0.5) * 0.6 + repel * (dy / (dist + 0.01)) * 0.6;

      // damping and drift with wind
      this.vx = this.vx * 0.96 + wind * 0.3;
      this.vy *= 0.96;
      this.x += this.vx;
      this.y += this.vy;

      // wrap
      if (this.x < -10) this.x = p.width + 10;
      if (this.x > p.width + 10) this.x = -10;
      if (this.y < -10) this.y = p.height * 0.6 + 10;
      if (this.y > p.height * 0.6 + 10) this.y = -10;
    }
    draw() {
      p.noStroke();
      const twinkle = 0.5 + 0.5 * p.sin(this.phase * 6 + t * 2);
      p.fill(230, 255, 180, 180);
      p.circle(this.x, this.y, this.size + twinkle);
    }
  }

  // --- Interaction ---
  p.mouseMoved = () => {
    // heat up when close to the fire
    var cx = p.width * 0.5;
    var cy = p.height * 0.72;
    const d = p.dist(p.mouseX, p.mouseY, cx, cy);
    const boost = p.constrain(1.6 - d / 220, 0.0, 0.8);
    heat = p.lerp(heat, 1 + boost, 0.2);
  };

  p.mouseDragged = () => {
    // handled in draw via movedX -> wind
  };

  function tossWord(x, y) {
    const pick = STORY[p.floor(p.random(STORY.length))];
    words.push(new WordSpark(pick, x, y));
    // micro heat burst
    heat = p.min(2.0, heat + 0.12);
  }

  p.mousePressed = () => {
    tossWord(p.mouseX, p.mouseY);
  };

  p.touchStarted = () => {
    tossWord(p.touches[0]?.x || p.width * 0.5, p.touches[0]?.y || p.height * 0.7);
    return false;
  };

  p.keyTyped = () => {
    if (p.key === 's' || p.key === 'S') {
      p.saveCanvas('epic-campfire', 'png');
      return;
    }
    // secret code tracking (letters only)
    if (/^[a-zA-Z]$/.test(p.key)) {
      typed = (typed + p.key.toUpperCase()).slice(-12);
      if (typed.endsWith('PHOENIX')) {
        phoenixTimer = 4.5; // seconds
        for (let i = 0; i < 80; i++) embers.push(new Ember());
        for (let j = 0; j < 12; j++) words.push(new WordSpark('🔥', p.width/2, p.height*0.7));
      }
    }
  };
};

new p5(campfireSketch);
